def main(write: bool) -> None:
    text = INDEX.read_text(encoding="utf-8")
    changed = []
    already = []
    for old, new in TITLE_REPLACEMENTS.items():
        old_count, new_count = text.count(old), text.count(new)
        assert (old_count, new_count) in {(1, 0), (0, 1)}, \
            f"неожиданное состояние заголовка: {old}"
        if old_count:
            text = text.replace(old, new)
            changed.append((old, new))
        else:
            already.append(new)

    def replace_card(old: str, new: str, label: str) -> bool:
        nonlocal text
        old_count, new_count = text.count(old), text.count(new)
        assert (old_count, new_count) in {(1, 0), (0, 1)}, \
            f"карточка {label} не найдена или неоднозначна"
        if old_count:
            text = text.replace(old, new)
            return True
        return False

    citibank_changed = replace_card(CITIBANK_OLD, CITIBANK_NEW, "Ренессанс Капитал — Ситибанк")
    selectel_changed = replace_card(SELECTEL_OLD, SELECTEL_NEW, "Selectel–ИТМО")
    agro_changed = replace_card(AGRO_OLD, AGRO_NEW, "Агростроя")

    print(f"Заголовков исправлено сейчас: {len(changed)}; уже исправлено: {len(already)}")
    print("Ренессанс Капитал — Ситибанк:", "исправлено" if citibank_changed else "уже соответствует стандарту")
    print("Selectel–ИТМО:", "исправлено" if selectel_changed else "уже соответствует стандарту")
    print("Агрострой:", "исправлено" if agro_changed else "уже соответствует стандарту")
    dirty = bool(changed or citibank_changed or selectel_changed or agro_changed)
    if write and dirty:
        INDEX.write_text(text, encoding="utf-8")
        print("Записано:", INDEX)
    elif write:
        print("Изменений нет: миграция уже применена.")
    else:
        print("Сухой прогон.", "Есть изменения; для записи добавьте --write." if dirty else "Миграция уже применена.")


if __name__ == "__main__":
    main("--write" in sys.argv)
